/** Public site languages; the dashboard and auth screens stay FR/EN (`Lang`). */
export type SiteLang = keyof typeof content;
export const siteLangs: { code: SiteLang; short: string; label: string }[] = [
  { code: "fr", short: "FR", label: "Français" },
  { code: "en", short: "EN", label: "English" },
  { code: "es", short: "ES", label: "Español" },
  { code: "pt", short: "PT", label: "Português" },
];
export const isSiteLang = (v: unknown): v is SiteLang => v === "fr" || v === "en" || v === "es" || v === "pt";
/** App screens (dashboard, auth) fall back to English for Spanish and Portuguese visitors. */
export const appLang = (l: SiteLang): Lang => (l === "fr" ? "fr" : "en");
/** Pick the string for the current site language. */
export const tr = <V,>(lang: SiteLang, values: Record<SiteLang, V>): V => values[lang];

